insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('sam-funded-two-lane-collection-2026-11-17','decision','A funded night runs two collection lanes on separate colleges (Sam, 2026-11-17)','Sam, relayed by COBIx on #3358 (2026-11-17): "my priority is completion and will find the funding to make it happen" and "Yes, run both tonight with separate colleges"; also "Yes, drop all retired courses". S680 ran the collection lane (twelve colleges) and the cheap-piles lane (every other college) with one writer a college.',array['program-requirements-harvest','conductor','collection','sam'],'proposed','COBIx on #3358; docs/reference/sam_rulings.md','Sam Lee, relayed by COBIx on #3358',null,'SkyPhoebe (S680)',date '2026-11-17'),
('sam-repo-size-limit-2026-11-17','decision','Move the bloated data out of the repo and hold it under a limit (Sam, 2026-11-17)','Sam, relayed by COBIx on #3358 and #3476 (2026-11-17): "Let''s move the bloated data out first thing and make sure we don''t allow to go beyond a limit." and "As cto you can restructure us." Carried out in S680 by #3495, #3498 and #3490; lane docs/reference/lanes/repo-size.md.',array['repo-size','infrastructure','receipts','sam'],'proposed','COBIx on #3358 and #3476; docs/reference/sam_rulings.md','Sam Lee, relayed by COBIx on #3358 and #3476',null,'SkyPhoebe (S680)',date '2026-11-17'),
('sam-conductor-back-for-collection-only-2026-11-17','decision','Conductor mode is back for collection only, in the CPL Queue routine (Sam, 2026-11-17)','The routine''s stored prompt (Sam, 2026-11-17): "Conductor mode is back for collection only." "Two lanes, never on the same college" "Spend caps: about $750 a day for everything. $10k and $30k are running totals for the whole job, not daily limits." "No new UI, tooling or governance work in conductor runs." "Stop a review after two rounds..."',array['conductor','scheduled-sessions','spend','sam'],'proposed','The CPL Queue routine''s stored prompt; docs/reference/conductor_mode.md','Sam Lee, the routine''s stored prompt (2026-11-17)',null,'SkyPhoebe (S680)',date '2026-11-17'),
('sam-collect-with-gaps-2026-11-17','decision','Never drop a record for failing: collect it with gaps and confidence (Sam, relayed in paraphrase)','Sam, relayed by COBIx on #3358 in paraphrase (no verbatim words): never drop a record for failing; collect it with its gaps noted and confidence scores, and report records collected and confidence gained, never "newly passing". #3497 stores its 75 no_units_read gaps as checks.gaps and checks.confidence.',array['program-requirements-harvest','commons','gaps','sam'],'proposed','COBIx on #3358 (paraphrase); docs/reference/sam_rulings.md','Sam Lee, relayed by COBIx on #3358 (paraphrase)',null,'SkyPhoebe (S680)',date '2026-11-17'),
('m-receipts-bucket-s680','milestone','Display receipts and old row audit reports live in the private bucket cpl-receipts','S680 (#3495, #3498 with #3501): the runner builds, stores and applies display receipts from the private bucket cpl-receipts (migrate run 44255184017); 141 display receipts (1,596.1 MB stored) and 165 row audit reports (982.5 MB) left the tree, each verified by sha256. The tree went from 4,862 MB to about 1,620 MB; #3490 guards the size.',array['repo-size','receipts','infrastructure'],'proposed','#3495, #3498, #3490; docs/reference/lanes/repo-size.md','SkyPhoebe (S680), the conductor',null,'SkyPhoebe (S680)',date '2026-11-18'),
('m-units-rules-applied-s680','milestone','Units rules A1, A4 and A5 applied to 56 program requirement records','S680 (#3496): 17 rows checks only (supabase-migrate run 44259625861) and 39 full row (run 44261575737), none skipped, after pre-read run 44258162212. Both rollbacks rebuilt from the returned rows, committed, not applied. 49 active programs move from failing to passing on the Commons count. kb/_guarded_sql.py writes every apply and rollback.',array['program-requirements-harvest','rule-10','units-rules'],'proposed','#3496; kb/migrations/2026-11-18_s680_prreq_units_rules_*.sql','SkyPhoebe (S680), the conductor',null,'SkyPhoebe (S680)',date '2026-11-18'),
('d-units-rule-a6-off-s680','decision','Units rule A6 stays off','S680 conductor (#3496): rule A6 was right on 0 of 4 held answers, so it ships off while A1, A4 and A5 apply. A rule that cannot be scored right on held answers is not applied.',array['program-requirements-harvest','units-rules'],'proposed','#3496','SkyPhoebe (S680), the conductor',null,'SkyPhoebe (S680)',date '2026-11-18'),
('f-miracosta-21976-live-newer-run-s680','fact','MiraCosta 21976''s live row is on a newer run than its filed record','S680 pre-read (run 44258162212): MiraCosta 21976 is live on run 38748842603 while its filed record is run 39726634443, so the units rules apply left it out. Read both before any write to it.',array['program-requirements-harvest','miracosta'],'proposed','#3496','SkyPhoebe (S680), the conductor',null,'SkyPhoebe (S680)',date '2026-11-18'),
('d-one-read-per-host-funded-night-s680','decision','On a funded night, step 11 runs one full outcome read per host','S680 conductor, under Sam''s "my priority is completion": since an outcome read costs runner minutes only, a funded night runs one full read per host instead of one a UTC day; never two runs on one host. 2,452 rows loaded at four colleges. docs/reference/scheduled_sessions.md step 11.',array['program-requirements-harvest','course-outcomes','scheduled-sessions'],'proposed','docs/reference/scheduled_sessions.md','SkyPhoebe (S680), the conductor',null,'SkyPhoebe (S680)',date '2026-11-18'),
('p-runner-pool-saturation-s680','pitfall','Outcome reads and same-night CI share one runner pool','S680: eight outcome runs plus CI on a dozen PRs saturated the runner pool; each CI took 25 to 40 minutes. A read is free in dollars and not in runner slots: cap concurrent reads when PRs must merge the same night.',array['conductor','ci','runners'],'proposed','docs/reference/conductor_mode.md, S680','SkyPhoebe (S680), the conductor',null,'SkyPhoebe (S680)',date '2026-11-18'),
('p-commons-data-rebuild-not-in-check-generated-s680','pitfall','check_generated.sh does not run CI''s Commons data check','S680: a PR that changes what the Commons data reads must rebuild commons_data.json in the same PR. scripts/check_generated.sh does not run that check and CI''s lints does, so three PRs went red. NEXT for a plain session: add the check to check_generated.sh.',array['commons','ci','generated-files'],'proposed','docs/reference/lanes/commons.md, S680','SkyPhoebe (S680), the conductor',null,'SkyPhoebe (S680)',date '2026-11-18'),
('pr-pr-chain-generated-conflicts-s680','procedure','Chain PRs when every merge conflicts a generated file; land shared-data PRs as one wave','S680: when each merge rewrites kb/dependency_map.json for every open PR, order the PRs once and chain them, each branch merging the one before it and rebuilding generated files with their builders; one worker assembles it. Shared-data PRs land as one wave; the checkpoint merges the wave and lands last.',array['conductor','merging','generated-files'],'proposed','docs/kb-notes/methodology-chain-prs-when-every-merge-conflicts-a-generated-file.md','SkyPhoebe (S680), the conductor',null,'SkyPhoebe (S680)',date '2026-11-18'),
('d-paid-rereads-need-aimed-input-s680','decision','No blind paid rereads: a reread needs an input aimed at the list','S680 conductor (#3502): the extractor has no input aimed at one list, and the same page and prompt give the same blocks (d-rccd-pilot-no-blind-force-s671). Two records with a changed page ($0.20) may reread; the rest wait on priced reader changes. 54 records whose figures do not add up or print no units take a named gap with no page read.',array['program-requirements-harvest','spend','rereads'],'proposed','#3502','SkyPhoebe (S680), the conductor',null,'SkyPhoebe (S680)',date '2026-11-18'),
('f-display-receipts-hold-no-person-data-s680','fact','The 141 committed display receipts hold no person data','S680: the conductor scanned all 141 display receipts committed before #3498 and found no email address and no person key, so the history rewrite (#3476 Part 5, Sam''s go) is a size question only; COBIx agreed.',array['repo-size','privacy','receipts'],'proposed','#3476; docs/reference/lanes/repo-size.md','SkyPhoebe (S680), the conductor',null,'SkyPhoebe (S680)',date '2026-11-18')
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
